describe("expression statements", () => {
  const cases: Array<[string, unknown]> = [
    ["a;", expression({type: "Identifier", name: "a"})],
    ["\"a\"", program({type: "ExpressionStatement", expression: {type: "Literal", value: "a", raw: "\"a\""}, directive: "a"})],
    ["a()", expression({type: "CallExpression", callee: {type: "Identifier", name: "a"}, arguments: []})],
    ["a = 1", expression({type: "AssignmentExpression", operator: "=", left: {type: "Identifier", name: "a"}, right: {type: "Literal", value: 1, raw: "1"}})],
    ["a; b", program({type: "ExpressionStatement", expression: {type: "Identifier", name: "a"}}, {type: "ExpressionStatement", expression: {type: "Identifier", name: "b"}})],
    ["a; b; c",
      program(
        {type: "ExpressionStatement", expression: {type: "Identifier", name: "a"}},
        {type: "ExpressionStatement", expression: {type: "Identifier", name: "b"}},
        {type: "ExpressionStatement", expression: {type: "Identifier", name: "c"}},
      )],
    ["a;\nb;", program({type: "ExpressionStatement", expression: {type: "Identifier", name: "a"}}, {type: "ExpressionStatement", expression: {type: "Identifier", name: "b"}})],
    ["f(); g()",
      program(
        {type: "ExpressionStatement", expression: {type: "CallExpression", callee: {type: "Identifier", name: "f"}, arguments: []}},
        {type: "ExpressionStatement", expression: {type: "CallExpression", callee: {type: "Identifier", name: "g"}, arguments: []}},
      )],
    ["a++; b--",
      program(
        {type: "ExpressionStatement", expression: {type: "UpdateExpression", operator: "++", prefix: false, argument: {type: "Identifier", name: "a"}}},
        {type: "ExpressionStatement", expression: {type: "UpdateExpression", operator: "--", prefix: false, argument: {type: "Identifier", name: "b"}}},
      )],
    ["new a", expression({type: "NewExpression", callee: {type: "Identifier", name: "a"}, arguments: []})],
    ["[a]", expression({type: "ArrayExpression", elements: [{type: "Identifier", name: "a"}]})],
    ["function f() {} a",
      program(
        {type: "FunctionDeclaration", id: {type: "Identifier", name: "f"}, params: [], body: {type: "BlockStatement", body: []}, expression: false},
        {type: "ExpressionStatement", expression: {type: "Identifier", name: "a"}},
      )],
    ["a\nfunction f() {}",
      program(
        {type: "ExpressionStatement", expression: {type: "Identifier", name: "a"}},
        {type: "FunctionDeclaration", id: {type: "Identifier", name: "f"}, params: [], body: {type: "BlockStatement", body: []}, expression: false},
      )],
    ["a = b\nc = d",
      program(
        {type: "ExpressionStatement", expression: {type: "AssignmentExpression", operator: "=", left: {type: "Identifier", name: "a"}, right: {type: "Identifier", name: "b"}}},
        {type: "ExpressionStatement", expression: {type: "AssignmentExpression", operator: "=", left: {type: "Identifier", name: "c"}, right: {type: "Identifier", name: "d"}}},
      )],
    ["\"a\"; \"b\"",
      program(
        {type: "ExpressionStatement", expression: {type: "Literal", value: "a", raw: "\"a\""}, directive: "a"},
        {type: "ExpressionStatement", expression: {type: "Literal", value: "b", raw: "\"b\""}, directive: "b"},
      )],
    ["a.b(); c.d()",
      program(
        {
          type: "ExpressionStatement",
          expression: {type: "CallExpression", callee: {type: "MemberExpression", object: {type: "Identifier", name: "a"}, property: {type: "Identifier", name: "b"}, computed: false}, arguments: []},
        },
        {
          type: "ExpressionStatement",
          expression: {type: "CallExpression", callee: {type: "MemberExpression", object: {type: "Identifier", name: "c"}, property: {type: "Identifier", name: "d"}, computed: false}, arguments: []},
        },
      )],
    ["x = y\n;z",
      program(
        {type: "ExpressionStatement", expression: {type: "AssignmentExpression", operator: "=", left: {type: "Identifier", name: "x"}, right: {type: "Identifier", name: "y"}}},
        {type: "ExpressionStatement", expression: {type: "Identifier", name: "z"}},
      )],
    ["a\n\nb", program({type: "ExpressionStatement", expression: {type: "Identifier", name: "a"}}, {type: "ExpressionStatement", expression: {type: "Identifier", name: "b"}})],
    ["a\n;\nb", program({type: "ExpressionStatement", expression: {type: "Identifier", name: "a"}}, {type: "ExpressionStatement", expression: {type: "Identifier", name: "b"}})],
  ];
  it.each(cases)("parse(%j)", (source, expected) => {
    const actual = parse(source);
    expect(actual, firstDifference(actual, expected) ?? "").toEqual(expected);
  });
});
